P=Path(__file__).resolve().parents[1];cats=['plants','buildings','materials','locations','quests'];D={c:json.loads((P/'data'/f'{c}.json').read_text()) for c in cats};I={(c,x['slug']):x for c,a in D.items() for x in a}; B='https://zombie-island.moy.su/';H={}
